const msg = $input.first().json.message || {};
const chatId = msg.chat?.id;
const text = (msg.text || msg.caption || '').trim();
const document = msg.document;
const command = text.startsWith('/') ? text.split(/\s+/)[0].toLowerCase() : '';

const allowed = ($env.TELEGRAM_ALLOWED_CHAT_IDS || '').split(',').map(s => s.trim()).filter(Boolean);
if (allowed.length && !allowed.includes(String(chatId))) {
  return [{ json: { chat_id: chatId, blocked: true, reply: 'Доступ запрещён.' } }];
}

return [{
  json: {
    chat_id: chatId,
    text,
    command,
    has_document: Boolean(document),
    file_id: document?.file_id || null,
    file_name: document?.file_name || 'upload.txt',
    mime_type: document?.mime_type || '',
    qdrant_url: $env.QDRANT_URL || 'http://localhost:6333',
    embedder_url: $env.EMBEDDER_URL || 'http://localhost:8081',
    collection: $env.RAG_COLLECTION || 'movetorussia_kb',
    deepseek_model: $env.DEEPSEEK_MODEL || 'deepseek-chat',
    top_k: Number($env.RAG_TOP_K || 6),
  }
}];

const item = $input.first();
const bin = item.binary?.data;
if (!bin?.data) throw new Error('Файл не загружен');

const sourceName = $('Parse Update').first().json.file_name || 'upload.txt';
const text = Buffer.from(bin.data, 'base64').toString('utf-8').replace(/\r\n/g, '\n').trim();
if (!text) throw new Error('Пустой файл');

const maxChars = 1800;
const overlap = 200;
const chunks = [];

function pseudoUuid(seed) {
  let a = 2166136261, b = 16777619, c = 0;
  for (let i = 0; i < seed.length; i++) {
    c = seed.charCodeAt(i);
    a ^= c; a = Math.imul(a, b);
    b = Math.imul(b, 2246822519) + c;
  }
  const p = (n, len) => (n >>> 0).toString(16).padStart(len, '0');
  return `${p(a,8)}-${p(b,4)}-${p(a ^ b,4)}-${p(b ^ a,4)}-${p(a + b,12)}`;
}

function pushChunk(body, idx) {
  const content = `[UPLOAD] Source: ${sourceName}\n\n${body}`;
  const id = pseudoUuid(`upload|${sourceName}|${idx}|${body.slice(0,200)}`);
  chunks.push({
    chunk_id: id,
    content,
    metadata: {
      source_type: 'telegram_upload',
      chunk_kind: 'text_upload',
      source_name: sourceName,
      chunk_index: idx,
    }
  });
}

const paragraphs = text.split(/\n{2,}/).map(p => p.trim()).filter(Boolean);
let buf = '';
let idx = 0;
for (const para of paragraphs.length ? paragraphs : [text]) {
  const candidate = buf ? `${buf}\n\n${para}` : para;
  if (candidate.length <= maxChars) {
    buf = candidate;
    continue;
  }
  if (buf) pushChunk(buf, idx++);
  if (para.length <= maxChars) {
    buf = para;
  } else {
    let start = 0;
    while (start < para.length) {
      const end = Math.min(start + maxChars, para.length);
      pushChunk(para.slice(start, end), idx++);
      if (end >= para.length) break;
      start = Math.max(end - overlap, start + 1);
    }
    buf = '';
  }
}
if (buf) pushChunk(buf, idx++);

const cfg = $('Parse Update').first().json;
return [{ json: { ...cfg, chunks, chunk_count: chunks.length, source_name: sourceName } }];

const cfg = $input.first().json;
const chunks = cfg.chunks || [];
if (!chunks.length) throw new Error('Нет чанков для индексации');

const batchSize = 16;
let indexed = 0;

for (let i = 0; i < chunks.length; i += batchSize) {
  const batch = chunks.slice(i, i + batchSize);
  const texts = batch.map(c => `passage: ${c.content}`);

  const embedResp = await this.helpers.httpRequest({
    method: 'POST',
    url: `${cfg.embedder_url.replace(/\/$/, '')}/embed`,
    body: { texts },
    json: true,
  });

  const points = batch.map((chunk, j) => ({
    id: chunk.chunk_id,
    vector: embedResp.embeddings[j],
    payload: { content: chunk.content, ...chunk.metadata },
  }));

  await this.helpers.httpRequest({
    method: 'PUT',
    url: `${cfg.qdrant_url.replace(/\/$/, '')}/collections/${cfg.collection}/points?wait=true`,
    body: { points },
    json: true,
  });

  indexed += batch.length;
}

return [{ json: { chat_id: cfg.chat_id, indexed, source_name: cfg.source_name, reply: `✅ Индексировано ${indexed} фрагментов из «${cfg.source_name}».` } }];

const cfg = $input.first().json;
const question = (cfg.text || '').trim();
if (!question) throw new Error('Пустой вопрос');
if (question.startsWith('/stats')) {
  const info = await this.helpers.httpRequest({
    method: 'GET',
    url: `${cfg.qdrant_url.replace(/\/$/, '')}/collections/${cfg.collection}`,
    json: true,
  });
  const points = info?.result?.points_count ?? info?.result?.vectors_count ?? '?';
  return [{ json: { chat_id: cfg.chat_id, reply: `Коллекция ${cfg.collection}: ${points} точек.` } }];
}

const embedResp = await this.helpers.httpRequest({
  method: 'POST',
  url: `${cfg.embedder_url.replace(/\/$/, '')}/embed`,
  body: { texts: [`query: ${question}`] },
  json: true,
});
const vector = embedResp.embeddings[0];

const searchResp = await this.helpers.httpRequest({
  method: 'POST',
  url: `${cfg.qdrant_url.replace(/\/$/, '')}/collections/${cfg.collection}/points/search`,
  body: {
    vector,
    limit: cfg.top_k,
    with_payload: true,
  },
  json: true,
});

const hits = searchResp?.result || [];
if (!hits.length) {
  return [{ json: { chat_id: cfg.chat_id, reply: 'В базе знаний не найдено релевантных фрагментов. Попробуйте переформулировать или загрузите материал через .txt файл.' } }];
}

const context = hits.map((h, i) => {
  const p = h.payload || {};
  const src = p.source_type || 'unknown';
  const score = (h.score ?? 0).toFixed(3);
  return `[${i + 1}] (${src}, score=${score})\n${p.content || ''}`;
}).join('\n\n---\n\n');

const systemPrompt = `Ты — внутренний ассистент MovetoRussia.com для менеджеров.
Отвечай ТОЛЬКО на основе контекста. Если данных недостаточно — скажи об этом.
Не выдумывай факты, суммы, сроки, ссылки. Язык ответа = язык вопроса.`;

const userPrompt = `Контекст:\n---\n${context}\n---\n\nВопрос: ${question}`;

const llmResp = await this.helpers.httpRequest({
  method: 'POST',
  url: `${($env.DEEPSEEK_BASE_URL || 'https://api.deepseek.com').replace(/\/$/, '')}/chat/completions`,
  headers: {
    Authorization: `Bearer ${$env.DEEPSEEK_API_KEY}`,
    'Content-Type': 'application/json',
  },
  body: {
    model: cfg.deepseek_model,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user', content: userPrompt },
    ],
    temperature: 0.2,
  },
  json: true,
});

let answer = llmResp?.choices?.[0]?.message?.content?.trim();
if (!answer) throw new Error('Пустой ответ DeepSeek');
if (answer.length > 3900) answer = answer.slice(0, 3900) + '…';

return [{ json: { chat_id: cfg.chat_id, reply: answer } }];
